# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency on artifacts.py (assumed available in same package or importable)
try:
    from hae.evaluation.artifacts import filter_bundle, is_generated_path, is_malformed_path
except ImportError:
