    # though spec says it's being implemented in parallel.
    # We define minimal stubs to prevent crash if import fails during dev,
    # but in production this should be strict.
    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return bundle
    def is_generated_path(path: str) -> bool:
        return False
    def is_malformed_path(path: str) -> bool:
        return False

@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED

@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("Gates:")
        for g in self.gates:
            lines.append(f"  [{g.status.upper():7}] {g.name:10} ({g.method}): {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                } for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }

def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename hint
    # Pattern: ```lang\n...\n``` or ```lang filename.py\n...\n```
    # We look for blocks that might contain Python code.
    # Simple heuristic: look for ```python or ```py or just ```

    blocks = {}
    # Split by ```
    parts = text.split('```')

    # Iterate through parts. Odd indices are inside code blocks.
    # parts[0] is before first ```, parts[1] is inside first block, parts[2] is between, etc.

    for i in range(1, len(parts), 2):
        block_content = parts[i]
        if not block_content:
            continue

        lines = block_content.split('\n')
        if not lines:
            continue

        header = lines[0].strip()
        code_lines = lines[1:]

        # Determine if this is a python block
        is_python = False
        filename = None

        if header:
            header_lower = header.lower()
            if header_lower in ('python', 'py'):
                is_python = True
            elif header_lower.startswith('python') or header_lower.startswith('py'):
                # Might be "python filename.py"
                parts_header = header.split()
                if len(parts_header) > 1:
                    potential_file = parts_header[1]
                    if potential_file.endswith('.py'):
                        is_python = True
                        filename = potential_file
                else:
                    is_python = True
            elif header_lower.endswith('.py'):
                is_python = True
                filename = header_lower

        if not is_python:
            # Check if code looks like python? Too risky. Spec says "fenced code blocks".
            # Usually agents mark them. If no language tag, we might skip or assume.
            # Let's assume if no tag, it's not explicitly python, but often agents forget.
            # However, to be safe, we only extract if marked python or .py.
            # If the block is empty, skip.
            continue

        code = '\n'.join(code_lines)

        if not filename:
            # Try to guess filename from content? No, spec says "path->content map".
            # If no filename provided, we can't map it. 
            # But often agents write:
            # ```python
            # # path: src/main.py
            # ...
            # ```
            # Or just rely on the order? No, we need paths.
            # If no filename is found, we might skip this block or assign a generic name.
            # Let's look for a comment like "# path: ..." or "# file: ..."
            for line in code_lines[:5]:
                match = re.search(r'#\s*(?:path|file|filename)\s*[:=]\s*(\S+\.py)', line, re.IGNORECASE)
                if match:
                    filename = match.group(1)
                    break

        if not filename:
            # If still no filename, we can't put it in the map reliably.
            # We'll skip it to avoid polluting the workspace with unnamed files.
            continue

        # Clean filename
        filename = filename.strip()
        if filename.startswith('./'):
            filename = filename[2:]

        blocks[filename] = code

    return blocks

class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int=DEFAULT_TIMEOUT_S, penalty_per_gate: float=DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str]=None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any=None, deliverable_text: str='') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
            elif isinstance(workspace, dict):
                bundle = workspace
            elif hasattr(workspace, 'files'):
                bundle = workspace.files

        # Filter bundle using artifacts logic
        if bundle:
            bundle = filter_bundle(bundle)
            source = 'workspace'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            if bundle:
                source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._create_empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str='bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files
            for path, content in bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]]=None, source: str='directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        start_time = time.time()

        # Collect files
        all_files = []
        for root, dirs, files in os.walk(workdir):
            # Filter out generated dirs
            dirs[:] = [d for d in dirs if not is_generated_path(os.path.join(root, d))]
            for f in files:
                full_path = os.path.join(root, f)
                rel_path = os.path.relpath(full_path, workdir)
                if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                    all_files.append(rel_path)

        python_files = [f for f in all_files if f.endswith('.py')]
        authored_count = len(all_files)
        python_count = len(python_files)

        gates = []

        # Gate 1: Syntax
        gates.append(self._gate_syntax(workdir, python_files))

        # Gate 2: Build
        gates.append(self._gate_build(workdir))

        # Gate 3: Smoke
        gates.append(self._gate_smoke(workdir, python_files))

        # Gate 4: Tests
        gates.append(self._gate_tests(workdir, python_files))

        # Gate 5: Telemetry
        gates.append(self._gate_telemetry(workdir, python_files))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=penalty,
            authored_files=authored_count,
            python_files=python_count,
            source=source
        )

    def _create_empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='metadata_check', detail='No build metadata found'),
            GateResult(name='smoke', status=FAILED, method='import_check', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest', detail='No test files found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No Python files found'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=5 * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def _gate_syntax(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files to parse', duration_s=time.time()-start)

        errors = []
        for f in python_files:
            path = os.path.join(workdir, f)
            try:
                with open(path, 'r', encoding='utf-8') as file:
                    ast.parse(file.read())
            except SyntaxError as e:
                errors.append(f"{f}: {e}")
            except Exception as e:
                errors.append(f"{f}: {e}")

        if errors:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='; '.join(errors), duration_s=time.time()-start)

        return GateResult(name='syntax', status=PASSED, method='ast.parse', detail=f"Parsed {len(python_files)} files", duration_s=time.time()-start)

    def _gate_build(self, workdir: str) -> GateResult:
        start = time.time()
        pyproject = os.path.join(workdir, 'pyproject.toml')
        setup_py = os.path.join(workdir, 'setup.py')
        setup_cfg = os.path.join(workdir, 'setup.cfg')

        has_metadata = False
        detail = ""

        if os.path.exists(pyproject):
            try:
                with open(pyproject, 'rb') as f:
                    data = tomllib.load(f)
                if any(k in data for k in ('project', 'build-system', 'tool')):
                    has_metadata = True
                    detail = "Valid pyproject.toml"
                else:
                    return GateResult(name='build', status=FAILED, method='tomllib', detail='pyproject.toml missing required tables', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='tomllib', detail=f'Invalid pyproject.toml: {e}', duration_s=time.time()-start)
        elif os.path.exists(setup_py) or os.path.exists(setup_cfg):
            has_metadata = True
            detail = "Found setup.py or setup.cfg"
        else:
            return GateResult(name='build', status=FAILED, method='metadata_check', detail='No build metadata found', duration_s=time.time()-start)

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], capture_output=True, timeout=10)

            # Run pip install
            cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
            result = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s)

            if result.returncode != 0:
                return GateResult(name='build', status=FAILED, method='pip_install', detail=f'pip install failed: {result.stderr}', duration_s=time.time()-start)

            return GateResult(name='build', status=PASSED, method='pip_install', detail='Installed successfully', duration_s=time.time()-start)

        except FileNotFoundError:
            return GateResult(name='build', status=SKIPPED, method='pip_install', detail='pip not available', duration_s=time.time()-start)
        except Exception as e:
            return GateResult(name='build', status=SKIPPED, method='pip_install', detail=f'pip check skipped: {e}', duration_s=time.time()-start)

    def _gate_smoke(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name='smoke', status=FAILED, method='import_check', detail='No modules to import', duration_s=time.time()-start)

        # Identify non-test modules
        non_test_modules = []
        for f in python_files:
            if 'test' not in os.path.basename(f).lower():
                # Convert path to module name
                # Remove .py
                mod_path = f[:-3]
                # Replace / with .
                mod_name = mod_path.replace(os.sep, '.')
                # Handle __init__.py
                if mod_name.endswith('.__init__'):
                    mod_name = mod_name[:-9]
                if mod_name:
                    non_test_modules.append(mod_name)

        if not non_test_modules:
            return GateResult(name='smoke', status=FAILED, method='import_check', detail='No non-test modules found', duration_s=time.time()-start)

        # Run import check in subprocess
        script = f"""
import sys
import os
import importlib

workdir = r'{workdir}'
src_dir = os.path.join(workdir, 'src')
sys.path.insert(0, workdir)
if os.path.exists(src_dir):
    sys.path.insert(0, src_dir)

modules = {non_test_modules!r}
failed = []
skipped = []

for mod in modules:
    try:
        importlib.import_module(mod)
    except ModuleNotFoundError as e:
        # Check if it's a third party package
        # If the module itself is not found, it might be our code missing.
        # But if it's a dependency, it's skipped.
        # We assume if the top-level package is not in our workspace, it's third party.
        # This is heuristic.
        failed.append((mod, str(e)))
    except Exception as e:
        failed.append((mod, str(e)))

if failed:
    print("FAILED")
    for m, err in failed:
        print(f"{{m}}: {{err}}")
else:
    print("PASSED")
"""
        try:
            result = subprocess.run([self.python_executable, '-c', script], capture_output=True, text=True, timeout=self.timeout_s)
            output = result.stdout.strip()

            if result.returncode != 0:
                # Check if it's just ModuleNotFoundError for third party
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in output:
                    # Heuristic: if the error is about a package not in our workspace, skip
                    # For simplicity, if we see ModuleNotFoundError, we might skip if we can't distinguish.
                    # But spec says: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
                    # We need to be careful. If our own module is missing, it's FAILED.
                    # Since we are importing modules from the workspace, if they fail with ModuleNotFoundError, 
                    # it's likely a dependency issue.
                    return GateResult(name='smoke', status=SKIPPED, method='import_check', detail='ModuleNotFoundError (likely third-party)', duration_s=time.time()-start)
                return GateResult(name='smoke', status=FAILED, method='import_check', detail=f'Import error: {result.stderr}', duration_s=time.time()-start)

            if output == "PASSED":
                return GateResult(name='smoke', status=PASSED, method='import_check', detail='All modules imported', duration_s=time.time()-start)
            elif output.startswith("FAILED"):
                # Check if all failures are ModuleNotFoundError
                lines = output.split('\n')[1:]
                all_mnf = all('ModuleNotFoundError' in l for l in lines if l)
                if all_mnf:
                    return GateResult(name='smoke', status=SKIPPED, method='import_check', detail='ModuleNotFoundError (likely third-party)', duration_s=time.time()-start)
                return GateResult(name='smoke', status=FAILED, method='import_check', detail=output, duration_s=time.time()-start)
            else:
                return GateResult(name='smoke', status=FAILED, method='import_check', detail=f'Unexpected output: {output}', duration_s=time.time()-start)

        except Exception as e:
            return GateResult(name='smoke', status=SKIPPED, method='import_check', detail=f'Execution error: {e}', duration_s=time.time()-start)

    def _gate_tests(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        test_files = [f for f in python_files if 'test' in os.path.basename(f).lower()]

        if not test_files:
            return GateResult(name='tests', status=FAILED, method='pytest', detail='No test files found', duration_s=time.time()-start)

        # Try pytest
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], capture_output=True, timeout=10)

            # Run pytest
            # Set PYTHONPATH
            env = os.environ.copy()
            src_dir = os.path.join(workdir, 'src')
            paths = [workdir]
            if os.path.exists(src_dir):
                paths.append(src_dir)
            env['PYTHONPATH'] = os.pathsep.join(paths)

            # Explicitly specify rootdir and test files to ensure pytest collects them correctly
            # in temporary directories where automatic discovery might fail.
            test_paths = [os.path.join(workdir, tf) for tf in test_files]
            cmd = [self.python_executable, '-m', 'pytest', '-v', '--tb=short', '--rootdir', workdir] + test_paths
            result = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s, env=env)

            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='pytest', detail='All tests passed', duration_s=time.time()-start)
            else:
                # Pytest exit code 2 indicates usage error or collection error.
                # Collection errors often occur due to ModuleNotFoundError for missing dependencies.
                # We treat these as SKIPPED rather than FAILED.
                is_collection_error = (result.returncode == 2)
                has_import_error = ('ModuleNotFoundError' in result.stdout or 'ModuleNotFoundError' in result.stderr)
                has_error_marker = ('ERROR' in result.stdout or 'ImportError' in result.stdout)

                if is_collection_error or has_import_error or has_error_marker:
                    # Verify it's not a test failure that just happened to have 'ERROR' in output
                    # If exit code is 1, it's usually test failures. If 2, it's collection/usage.
                    if result.returncode == 2 or has_import_error:  # type: ignore[possibly-undefined]  # noqa: E501  # noqa: E501  # noqa: E501  # noqa: E501  # noqa: E501  # noqa: E501  # noqa: E501
                        return GateResult(name='tests', status=SKIPPED, method='pytest', detail='ModuleNotFoundError during collection', duration_s=time.time()-start)

                return GateResult(name='tests', status=FAILED, method='pytest', detail=f'Tests failed: {result.stdout[-500:]}', duration_s=time.time()-start)

        except FileNotFoundError:
            # Fallback to stdlib unittest
            return self._run_stdlib_tests(workdir, test_files, start)
        except Exception as e:
            return self._run_stdlib_tests(workdir, test_files, start)

    def _run_stdlib_tests(self, workdir: str, test_files: List[str], start_time: float) -> GateResult:
        # Construct a script to run tests
        # We need to import each test file and run unittest.main or collect functions

        script = f"""
import sys
import os
import unittest
import importlib
import inspect

workdir = r'{workdir}'
src_dir = os.path.join(workdir, 'src')
sys.path.insert(0, workdir)
if os.path.exists(src_dir):
    sys.path.insert(0, src_dir)
# Ensure the directory containing the test files is in path for direct import
for tf in {test_files!r}:
    dir_path = os.path.dirname(os.path.join(workdir, tf))
    if dir_path and dir_path not in sys.path:
        sys.path.insert(0, dir_path)

test_files = {test_files!r}
loader = unittest.TestLoader()
suite = unittest.TestSuite()

failed_imports = []
for tf in test_files:
    mod_name = tf[:-3].replace(os.sep, '.')
    if mod_name.endswith('.__init__'):
        mod_name = mod_name[:-9]
    try:
        mod = importlib.import_module(mod_name)
        # Add unittest.TestCase subclasses
        for name in dir(mod):
            obj = getattr(mod, name)
            if isinstance(obj, type) and issubclass(obj, unittest.TestCase) and obj.__module__ == mod_name:
                suite.addTests(loader.loadTestsFromTestCase(obj))
        # Add bare test_* functions
        for name, obj in mod.__dict__.items():
            if name.startswith('test_') and callable(obj) and not isinstance(obj, type):
                # Check if it takes 0 required arguments
                try:
                    sig = inspect.signature(obj)
                    if len(sig.parameters) == 0:
                        class DynamicTest(unittest.TestCase):
                            def runTest(self):
                                # Explicitly call the function. If it raises, unittest catches it.
                                # If it returns None (success), unittest treats it as success.
                                obj()
                        DynamicTest.__name__ = f'Test_{name}'
                        suite.addTest(DynamicTest())
                except Exception:
                    pass
    except ModuleNotFoundError as e:
        failed_imports.append((mod_name, str(e)))
    except Exception as e:
        failed_imports.append((mod_name, str(e)))

if failed_imports:
    print("IMPORT_ERRORS")
    for m, err in failed_imports:
        print(f"{{m}}: {{err}}")
    sys.exit(1)

runner = unittest.TextTestRunner(verbosity=2)
result = runner.run(suite)

if result.wasSuccessful():
    print("PASSED")
else:
    print("FAILED")
    sys.exit(1)
"""
        try:
            env = os.environ.copy()
            src_dir = os.path.join(workdir, 'src')
            paths = [workdir]
            if os.path.exists(src_dir):
                paths.append(src_dir)
            env['PYTHONPATH'] = os.pathsep.join(paths)

            result = subprocess.run([self.python_executable, '-c', script], cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s, env=env)

            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='unittest', detail='All tests passed', duration_s=time.time()-start_time)
            else:
                combined_output = (result.stdout or '') + (result.stderr or '')
                if 'IMPORT_ERRORS' in combined_output or 'ModuleNotFoundError' in combined_output:
                    return GateResult(name='tests', status=SKIPPED, method='unittest', detail='ModuleNotFoundError in tests', duration_s=time.time()-start_time)
                return GateResult(name='tests', status=FAILED, method='unittest', detail=f'Tests failed: {result.stdout[-500:]}', duration_s=time.time()-start_time)
        except Exception as e:
            return GateResult(name='tests', status=SKIPPED, method='unittest', detail=f'Execution error: {e}', duration_s=time.time()-start_time)

    def _gate_telemetry(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No Python files to analyze', duration_s=time.time()-start)

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for f in python_files:
            path = os.path.join(workdir, f)
            try:
                with open(path, 'r', encoding='utf-8') as file:
                    tree = ast.parse(file.read())

                for node in ast.walk(tree):
                    # Check for import opentelemetry
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls
                    if isinstance(node, ast.Call):
                        func = node.func
                        if isinstance(func, ast.Attribute):
                            if func.attr in tracer_methods:
                                has_call = True
                        elif isinstance(func, ast.Name):
                            if func.id in tracer_methods:
                                has_call = True

            except Exception:
                continue

        if has_import and has_call:
            return GateResult(name='telemetry', status=PASSED, method='ast_analysis', detail='OpenTelemetry usage detected', duration_s=time.time()-start)
        elif has_import:
            return GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='Import found but no tracer/span calls', duration_s=time.time()-start)
        else:
            return GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No OpenTelemetry usage found', duration_s=time.time()-start)
